 *     so the Buffer shape is (M, N) == (columns, rows).
 */
static void init_array(int m,
                       int n,
                       num_t *float_n,
                       Halide::Buffer<num_t, 2> data) {
    // float_n = N in the original code; here N == n
    *float_n = (num_t)n;

    Var i("i"), j("j");
    Func init_data("init_data");

    // C: data[i][j] = (DATA_TYPE)(i*j)/M + i;
    // Mapping: data[i][j] -> data(j, i)
    Expr m_expr = Expr(m);

    init_data(j, i) =
