    num_t float_n;

    // Buffers:
    // C: DATA_TYPE data[N][M];
    // Map to Halide Buffer with shape (M, N) and access as data(j, i).
    Halide::Buffer<num_t, 2> data_buf(m, n);

    // C: DATA_TYPE corr[M][M];
    // Map to Halide Buffer with shape (M, M) and access as corr(j, i).
    Halide::Buffer<num_t, 2> corr_buf(m, m);

    // Initialize input data and scalar
    init_array(m, n, &float_n, data_buf);

    // --- Build the Halide pipeline that implements kernel_correlation ---

    // ImageParam for the input data
    ImageParam data_param(type_of<num_t>(), 2, "data_param");
    // Param for float_n
    Param<num_t> float_n_param("float_n_param");

    data_param.set(data_buf);
    float_n_param.set(float_n);

    // Vars
    Var j("j"), i("i");     // j: column index, i: row index
    Var p("p"), q("q");     // indices for correlation matrix

    // Reduction domain over rows (0 .. n-1)
    RDom r_i(0, data_param.dim(1).extent(), "r_i");

    // ------------------------------------------------------------------
    // 1) mean[j] = (1 / float_n) * sum_i data[i][j]
    // ------------------------------------------------------------------
    Func mean_sum("mean_sum");
    Func mean("mean");

    // sum_i data[i][j]
    mean_sum(j) = cast<num_t>(0);
    mean_sum(j) += data_param(j, r_i);  // data[i][j] -> data_param(j, i=r_i)

    // divide by float_n
    mean(j) = mean_sum(j) / float_n_param;

    // ------------------------------------------------------------------
    // 2) stddev[j] from original (before normalization):
    //
    //    stddev[j] = 0;
    //    for i: stddev[j] += (data[i][j] - mean[j])^2;
    //    stddev[j] /= float_n;
    //    stddev[j] = sqrt(stddev[j]);
    //    if stddev[j] <= eps: stddev[j] = 1.0;
    // ------------------------------------------------------------------
    Func stddev_sum("stddev_sum");
    Func stddev_pre("stddev_pre");
    Func stddev_sqrt("stddev_sqrt");
    Func stddev("stddev");

    stddev_sum(j) = cast<num_t>(0);
    stddev_sum(j) += (data_param(j, r_i) - mean(j)) *
                     (data_param(j, r_i) - mean(j));

    stddev_pre(j) = stddev_sum(j) / float_n_param;
    stddev_sqrt(j) = sqrt(stddev_pre(j));

    Expr eps = cast<num_t>(Expr(0.1));   // SCALAR_VAL(0.1)
    stddev(j) = select(stddev_sqrt(j) <= eps,
                       cast<num_t>(Expr(1.0)),  // SCALAR_VAL(1.0)
                       stddev_sqrt(j));

    // ------------------------------------------------------------------
    // 3) Center and normalize data:
    //
    //    data[i][j] -= mean[j];
    //    data[i][j] /= sqrt(float_n) * stddev[j];
    //
    // We represent the normalized data as a separate Func:
    //    norm(j, i) = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
    // ------------------------------------------------------------------
    Func norm("norm");
    Expr sqrt_float_n = sqrt(float_n_param);

    norm(j, i) =
        (data_param(j, i) - mean(j)) / (sqrt_float_n * stddev(j));

    // ------------------------------------------------------------------
    // 4) Correlation matrix:
    //
    // C code:
    //   for (i = 0; i < m-1; i++) {
    //     corr[i][i] = 1.0;
    //     for (j = i+1; j < m; j++) {
    //       corr[i][j] = 0.0;
    //       for (k = 0; k < n; k++)
