    //       corr[j][i] = corr[i][j];
    //     }
    //   }
    //   corr[m-1][m-1] = 1.0;
    //
    // We compute the full symmetric matrix as a reduction over k, then
    // force the diagonal to be 1.0 (matching the C code).
    // ------------------------------------------------------------------
    RDom r_k(0, data_param.dim(1).extent(), "r_k");  // k over rows

    Func corr_sum("corr_sum");
    Func corr("corr");

    // Inner products of normalized columns:
    corr_sum(p, q) = cast<num_t>(0);
    corr_sum(p, q) += norm(p, r_k) * norm(q, r_k);

    // Force diagonal to be exactly 1.0 as in the C code.
    corr(p, q) = select(p == q,
                        cast<num_t>(Expr(1.0)),  // corr[i][i] = 1.0
                        corr_sum(p, q));

    // A simple schedule: keep arguments in (p, q) order, and keep the
    // reduction variable innermost.
    corr.reorder(p, q);
    corr_sum.update().reorder(p, q, r_k);

    // Compile the pipeline
    corr.compile_jit();

    // Measure execution time of running the kernel once
    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: fill corr_buf with the correlation matrix
    corr.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results (like PolyBench's print_array),
    // following the pattern used in gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                // corr[i][j] in C corresponds to corr_buf(j, i) here
                std::cerr << corr_buf(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

