using num_t = DATA_TYPE;

/**
 * Initialize the input array `data` and scalar `float_n`, matching
 * the semantics of the original C init_array():
 *
 *   *float_n = (DATA_TYPE)N;
 *   for (i = 0; i < N; i++)
 *     for (j = 0; j < M; j++)
 *       data[i][j] = (DATA_TYPE)(i*j)/M + i;
 *
 * The C layout data[i][j] (N x M) is mapped to Halide Buffer with
 * shape (M, N) and accessed as data(j, i).
 */
static void init_array(int m, int n,
                       num_t *float_n,
                       Halide::Buffer<num_t, 2> data) {
    // In the original code: *float_n = (DATA_TYPE)N;
    *float_n = static_cast<num_t>(n);

    // Halide-based initialization of data:
    Var i("i"), j("j");
    Func init_data("init_data");

    // data[i][j] = (DATA_TYPE)(i*j)/M + i;
    // Map to Halide as data(j, i).
    Expr m_expr = Expr(m);  // integer Expr
    init_data(j, i) =
        cast<num_t>(i * j) / cast<num_t>(m_expr) +
        cast<num_t>(i);

    init_data.realize(data);
}

int main(int argc, char *argv[]) {
    // Problem sizes: N rows, M columns.
    int n = N;
    int m = M;

    // Host-side data structures (PolyBench-style).
    num_t float_n;

    // Map C arrays:
    //   data[N][M]  -> Buffer(m, n) accessed as data(j, i)
    //   corr[M][M]  -> Buffer(m, m) accessed as corr(j, i)
    Halide::Buffer<num_t, 2> data(m, n);
    Halide::Buffer<num_t, 2> corr(m, m);

    // Initialize input data.
    init_array(m, n, &float_n, data);

    //-------------------------------
    // Build the Halide correlation pipeline
    //-------------------------------

    // Input image parameter: original data matrix.
    ImageParam data_param(type_of<num_t>(), 2, "data_param");
    data_param.set(data);  // Bind to our input buffer.

    // Vars.
    Var i("i"), j("j");

    // Scalar constants as Exprs.
    Expr float_n_expr = Expr(float_n);                          // (DATA_TYPE)N
    Expr eps_expr      = cast<num_t>(Expr(0.1));                // SCALAR_VAL(0.1)
    Expr one_expr      = cast<num_t>(Expr(1.0));                // SCALAR_VAL(1.0)

    // 1) Compute mean[j] = (1/float_n) * sum_i data[i][j]

    // First accumulate sums over rows (i).
    Func mean_sum("mean_sum");
    RDom r_mean(0, data_param.dim(1).extent(), "r_mean");  // r_mean in [0..N-1]

    mean_sum(j) = cast<num_t>(Expr(0));          // initialize to 0
    mean_sum(j) += data_param(j, r_mean);        // sum over i

    Func mean("mean");
    mean(j) = mean_sum(j) / float_n_expr;

    // 2) Compute stddev[j]
    //
    // stddev[j] = sqrt( (1/float_n) * sum_i (data[i][j] - mean[j])^2 )
    // stddev[j] = (stddev[j] <= eps) ? 1.0 : stddev[j];

    Func stddev_sum("stddev_sum");
    RDom r_std(0, data_param.dim(1).extent(), "r_std");  // r_std in [0..N-1]

    stddev_sum(j) = cast<num_t>(Expr(0));
    {
        Expr diff = data_param(j, r_std) - mean(j);
        stddev_sum(j) += diff * diff;
    }

    Func stddev("stddev");
    {
        Expr variance = stddev_sum(j) / float_n_expr;
        Expr sigma    = Halide::sqrt(variance);
        stddev(j)     = select(sigma <= eps_expr, one_expr, sigma);
    }

    // 3) Normalize data to produce data_norm:
    //
    // data[i][j] -= mean[j];
    // data[i][j] /= sqrt(float_n) * stddev[j];
    //
    // We'll implement this functionally as:
    // data_norm(j, i) = (data[j, i] - mean[j]) / (sqrt(float_n) * stddev[j]);

    Func data_norm("data_norm");
    {
        Expr sqrt_float_n = Halide::sqrt(float_n_expr);
        data_norm(j, i) =
            (data_param(j, i) - mean(j)) / (sqrt_float_n * stddev(j));
    }

    // 4) Compute the correlation matrix corr[i][j].
    //
    // Original C code:
    //
    // for (i = 0; i < M-1; i++) {
    //   corr[i][i] = 1.0;
    //   for (j = i+1; j < M; j++) {
    //     corr[i][j] = 0.0;
    //     for (k = 0; k < N; k++)
    //       corr[i][j] += data[k][i] * data[k][j];
    //     corr[j][i] = corr[i][j];
    //   }
    // }
    // corr[M-1][M-1] = 1.0;
    //
    // We compute a symmetric matrix by using
    // sum_k data_norm[min(i,j)][k] * data_norm[max(i,j)][k]
    // for all (i, j), and then explicitly force the diagonal to 1.0.

    Func corr_raw("corr_raw");
    RDom r_corr(0, data_param.dim(1).extent(), "r_corr");  // k in [0..N-1]

    corr_raw(i, j) = cast<num_t>(Expr(0));

    {
        Expr col_min = Halide::min(i, j);
        Expr col_max = Halide::max(i, j);
        corr_raw(i, j) +=
            data_norm(col_min, r_corr) * data_norm(col_max, r_corr);
    }

    // Force the diagonal to 1.0, to match the original kernel.
    Func corr_final("corr_final");
    corr_final(i, j) = select(i == j, one_expr, corr_raw(i, j));

    // (Optional) Simple schedule to make loops explicit and
    // roughly row-major over i, j.
    corr_final.reorder(j, i);

    // JIT-compile once, separate from timing.
    corr_final.compile_jit();

    //-------------------------------
    // Run and time the pipeline
    //-------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Realize the correlation matrix into `corr`.
    corr_final.realize(corr);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    //-------------------------------
    // Optionally print results (like PolyBench DCE protection)
    //-------------------------------

    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr[ii][jj] in C corresponds to corr(jj, ii) in Halide.
                std::cerr << corr(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
