#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, M, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "correlation.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the input data array, matching the PolyBench C version:
 *
 *   *float_n = (DATA_TYPE)N;
 *   for (i = 0; i < N; i++)
 *     for (j = 0; j < M; j++)
 *       data[i][j] = (DATA_TYPE)(i*j)/M + i;
 *
 * C array data[i][j] (N x M) is mapped to a Halide::Buffer with shape (M, N)
 * and accessed as data(j, i).
 */
static
void init_array(int m, int n,
                num_t *float_n,
                Halide::Buffer<num_t, 2> data) {
    // float_n is just the (float) number of rows n (== N)
    *float_n = (num_t)n;

    Var i("i"), j("j");
    Func init_data("init_data");

    // data(i,j) in C -> data(j,i) in Halide
    // (DATA_TYPE)(i*j)/M + i;
    Expr val_int = (i * j) / m;  // integer division, as in C
    init_data(j, i) = cast<num_t>(val_int) + cast<num_t>(i);

    init_data.realize(data);
}

int main(int argc, char *argv[]) {
    // Problem size (from correlation.hpp / defines.hpp)
    int n = N;  // number of rows (observations)
    int m = M;  // number of columns (variables)

    // Input and output data
    num_t float_n;

    // C: DATA_TYPE data[N][M]  -> Halide Buffer(M, N), accessed as (j, i)
    Halide::Buffer<num_t, 2> data(m, n);

    // C: DATA_TYPE corr[M][M] -> Halide Buffer(M, M), accessed as (j, i)
    Halide::Buffer<num_t, 2> corr(m, m);

    // Initialize input data
    init_array(m, n, &float_n, data);

    // Halide parameters corresponding to C arguments
    ImageParam data_param(type_of<num_t>(), 2, "data_param");
    Param<num_t> float_n_param("float_n_param");

    data_param.set(data);
    float_n_param.set(float_n);

    // Vars and reduction domains
    Var i("i"), j("j");
    RDom r_i(0, n, "r_i");  // over rows
    RDom r_s(0, n, "r_s");  // for stddev
    RDom k(0, n, "k");      // for correlation

    // ---- Mean computation ----
    // mean[j] = sum_i data[i][j] / float_n;
    Func mean_sum("mean_sum"), mean("mean");

    mean_sum(j) = cast<num_t>(0);
    mean_sum(j) += data_param(j, r_i);    // data[i][j] -> data_param(j, r_i)
    mean(j) = mean_sum(j) / float_n_param;

    // ---- Stddev computation ----
    // stddev[j] = sqrt( sum_i (data[i][j] - mean[j])^2 / float_n );
    // stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    Func stddev_accum("stddev_accum");
    Func stddev("stddev");
    Func stddev_clamped("stddev_clamped");

    stddev_accum(j) = cast<num_t>(0);
    {
        Expr diff = data_param(j, r_s) - mean(j);
        stddev_accum(j) += diff * diff;
    }

    stddev(j) = sqrt(stddev_accum(j) / float_n_param);

    Expr eps = cast<num_t>(0.1);
    Expr one = cast<num_t>(1.0);
    stddev_clamped(j) = select(stddev(j) <= eps, one, stddev(j));

    // ---- Center and reduce the column vectors ----
    // data'[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j]);
    Func norm("norm");
    Expr float_n_sqrt = sqrt(float_n_param);

    norm(j, i) = (data_param(j, i) - mean(j)) /
                 (float_n_sqrt * stddev_clamped(j));

    // ---- Correlation matrix ----
    // For i != j:
    //   corr[i][j] = sum_k data'[k][i] * data'[k][j];
    // Symmetric: corr[j][i] = corr[i][j];
    // Diagonal set to 1.0 explicitly.
    //
    // We'll compute the full symmetric matrix via a reduction:
    //   corr_accum(i, j) = sum_k norm(i, k) * norm(j, k);
    // and then override the diagonal with 1.0.
    Func corr_accum("corr_accum"), corr_final("corr_final");

    corr_accum(j, i) = cast<num_t>(0);
    corr_accum(j, i) += norm(j, k) * norm(i, k);

    // Set diagonal to 1.0, as in the C code.
    corr_final(j, i) = select(i == j, one, corr_accum(j, i));

    // JIT-compile the pipeline
    corr_final.compile_jit();

    // Measure execution time of the kernel (one realization)
    auto start = std::chrono::high_resolution_clock::now();

    corr_final.realize(corr);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the output correlation matrix, similar to PolyBench
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_c = 0; i_c < m; i_c++) {      // C's i index
            for (int j_c = 0; j_c < m; j_c++) {  // C's j index
                // C: corr[i][j] -> Halide: corr(j, i)
                std::cerr << corr(j_c, i_c) << '\n';
            }
        }
    }

    // Print kernel execution time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
