#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, M, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "correlation.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize the input array using the same formula as the C version.
//
// C code:
//   *float_n = (DATA_TYPE)N;
//   for (i = 0; i < N; i++)
//     for (j = 0; j < M; j++)
//       data[i][j] = (DATA_TYPE)(i*j)/M + i;
//
// Mapping to Halide:
//   C:  data[i][j]  -> Halide Buffer(j, i)
//   Buffer has shape (M, N), accessed as data(j, i).
static void init_array(int m, int n,
                       num_t *float_n,
                       Halide::Buffer<num_t, 2> data) {
    // float_n = (DATA_TYPE)N;  (here N == n)
    *float_n = (num_t)n;

    Var i("i"), j("j");
    Func init_data("init_data");

    // data[i][j] = (DATA_TYPE)(i*j)/M + i;
    // -> init_data(j, i) = (i * j) / m + i
    // Use Expr(...) to construct Halide expressions from C++ scalars.
    init_data(j, i) =
        cast<num_t>(i * j) / Expr(m) + cast<num_t>(i);

    init_data.realize(data);
}

int main(int argc, char *argv[]) {
    // Problem size (N samples, M variables)
    int n = N;
    int m = M;

    // Input and output data
    num_t float_n;
    // data: shape (M, N) so that data(j, i) corresponds to C's data[i][j]
    Halide::Buffer<num_t, 2> data(m, n);
    // corr: shape (M, M), corr(j, i) corresponds to C's corr[i][j]
    Halide::Buffer<num_t, 2> corr(m, m);

    // Initialize input data
    init_array(m, n, &float_n, data);

    // Halide parameters and Vars
    ImageParam data_param(type_of<num_t>(), 2, "data_param");
    Param<num_t> float_n_param("float_n_param");

    Var j("j"), i("i");

    // Bind runtime parameters
    data_param.set(data);
    float_n_param.set(float_n);

    // -------------------------
    // Build the Halide pipeline
    // -------------------------

    // mean[j] = (1 / float_n) * sum_{i=0..n-1} data[i][j]
    Func mean_sum("mean_sum");
    RDom r_mean(0, data.height(), "r_mean");  // iterate over samples (rows)
    mean_sum(j) = Expr((num_t)0);
    mean_sum(j) += data_param(j, r_mean);

    Func mean("mean");
    mean(j) = mean_sum(j) / float_n_param;

    // stddev[j] = sqrt( (1 / float_n) * sum_i (data[i][j] - mean[j])^2 )
    // with clamping for small values
    Func var_sum("var_sum");
    RDom r_var(0, data.height(), "r_var");
    var_sum(j) = Expr((num_t)0);
    {
        Expr diff = data_param(j, r_var) - mean(j);
        var_sum(j) += diff * diff;
    }

    Func stddev_raw("stddev_raw");
    stddev_raw(j) = sqrt(var_sum(j) / float_n_param);

    // eps = 0.1; stddev[j] = (stddev_raw[j] <= eps) ? 1.0 : stddev_raw[j];
    Expr eps = Expr((num_t)0.1);
    Func stddev("stddev");
    stddev(j) = select(stddev_raw(j) <= eps,
                       Expr((num_t)1.0),
                       stddev_raw(j));

    // Center and reduce the column vectors:
    // data_norm[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j]);
    Func data_norm("data_norm");
    data_norm(j, i) =
        (data_param(j, i) - mean(j)) /
        (sqrt(float_n_param) * stddev(j));

    // Compute correlation matrix:
    //
    // C code:
    //   for (i = 0; i < M-1; i++) {
    //     corr[i][i] = 1.0;
    //     for (j = i+1; j < M; j++) {
    //       corr[i][j] = 0.0;
    //       for (k = 0; k < N; k++)
    //         corr[i][j] += data[k][i] * data[k][j];
    //       corr[j][i] = corr[i][j];
    //     }
    //   }
    //   corr[M-1][M-1] = 1.0;
    //
    // We compute the full symmetric matrix directly via:
    //   corr[p][q] = sum_k data_norm[k][p] * data_norm[k][q],
    // then set the diagonal explicitly to 1.0.
    Var p("p"), q("q");
    RDom k(0, data.height(), "k");  // sum over samples

    Func corr_func("corr_func");
    corr_func(p, q) = Expr((num_t)0);
    corr_func(p, q) += data_norm(p, k) * data_norm(q, k);

    // Force the diagonal to exactly 1.0 (matching the C code)
    RDom r_diag(0, data.width(), "r_diag");  // over variables (0..M-1)
    corr_func(r_diag, r_diag) = Expr((num_t)1.0);

    // (Optional) We could add explicit scheduling here to match
    // the original traversal order, but the default schedule
    // already computes the correct result, so we leave it as-is.

    // JIT-compile the pipeline
    corr_func.compile_jit();

    // --------------------------
    // Run and time the pipeline
    // --------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: compute corr into the 'corr' buffer
    corr_func.realize(corr);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------
    // Print results (like print_array)
    // --------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_idx = 0; i_idx < m; i_idx++) {
            for (int j_idx = 0; j_idx < m; j_idx++) {
                // C: corr[i][j]  -> Halide: corr(j, i)
                std::cerr << corr(j_idx, i_idx) << '\n';
            }
        }
    }

    // Print timing in seconds (to stdout)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
